pages.practice=()=>`<section class="practice-room"><div class="wrap">${methodNav('practice')}<div class="split"><div><span class="eyebrow">INTO THE LIFE YOU ALREADY HAVE</span><h1>Let a little truth<br><span class="marker">come with you.</span></h1><p>Romans 8:12–17 describes belonging to God’s family. What could change in one ordinary moment if you began from that belonging?</p><div class="share-slip hand">One honest prayer.<br>No impressive introduction.</div><p>Try this: before your next prayer, pause. Begin in your own voice. If the word Father is difficult, bring that difficulty honestly, too.</p>${go('quests','Or choose a little Side Quest ↗','text-link')}</div><article class="share-paper"><span class="eyebrow">A SMALL EXPERIMENT, NOT A PERFECT PLAN</span><h2>Where could this meet your day?</h2><label for="practice-when">When I…</label><input id="practice-when" placeholder="sit down with my tea tomorrow morning…"><label for="practice-try">I could try…</label><textarea id="practice-try" placeholder="one prayer in my own words, without polishing it first…"></textarea><details><summary>Why this little experiment? ↓</summary><p>Connect your practice to the passage. What does Paul say about the Spirit, fear, and being God’s children? Use those verses to check your understanding.</p></details><details><summary>When you come back… ↓</summary><p>Without rereading first, what do you remember about belonging? Then reopen Romans 8:12–17. What did you notice in the experiment? It is fine if the answer is a question rather than a breakthrough.</p></details><div class="actions">${go('share','Keep or share what you noticed →')}</div><p class="quiet">Your plan stays in this browser tab as you move between pages. Download anything you want to keep before closing it.</p></article></div></div></section>`;

// Review fixes: trustworthy daily state, focus continuity, and temporary drafts.
const showCardBeforeRefinement=showCard;
showCard=function(){const focused=document.activeElement?.id;showCardBeforeRefinement();const stage=document.querySelector('#card-stage');if(cardDrawer==='today'&&activeCard!==dailyIndex()){stage.querySelector('.card-tab').textContent='ANOTHER DISCOVERY';stage.querySelector('.card-discovery').insertAdjacentHTML('beforeend','<button class="small secondary" id="return-today">Return to today’s card</button>');document.querySelector('#return-today').onclick=()=>{activeCard=dailyIndex();cardBack=false;showCard();document.querySelector('#turn-card')?.focus();};}if(cardDrawer!=='archive'){stage.querySelector('.card-actions').insertAdjacentHTML('beforeend','<button class="small secondary" id="print-card">Print this card</button>');document.querySelector('#print-card').onclick=()=>window.print();}if(focused&&stage.querySelector('#'+focused))stage.querySelector('#'+focused).focus({preventScroll:true});if(focused==='back-today')stage.querySelector('#turn-card')?.focus();};
const teachingBeforeRefinement=teachingPreview;
teachingPreview=function(){teachingBeforeRefinement();document.querySelectorAll('[data-teaching]').forEach(b=>b.setAttribute('aria-controls','teaching-preview'));};
const transientDrafts={};
const renderBeforeDrafts=render;
window.removeEventListener('hashchange',renderBeforeDrafts);
render=function(){const oldRoute=document.body.dataset.room;if(['make','journal','share','practice'].includes(oldRoute)){const fields={};document.querySelectorAll('main input[id],main textarea[id]').forEach(el=>fields[el.id]=el.value);transientDrafts[oldRoute]={fields,sketch:document.querySelector('#sketch')?.toDataURL(),mode:document.querySelector('[data-make-mode][aria-pressed=true]')?.dataset.makeMode};}renderBeforeDrafts();const route=document.body.dataset.room,draft=transientDrafts[route];if(draft){Object.entries(draft.fields).forEach(([id,v])=>{const el=document.getElementById(id);if(el)el.value=v;});if(draft.mode)document.querySelector('[data-make-mode="'+draft.mode+'"]')?.click();if(draft.sketch&&document.querySelector('#sketch')){const im=new Image();im.onload=()=>document.querySelector('#sketch')?.getContext('2d').drawImage(im,0,0);im.src=draft.sketch;}}if(route==='make'){document.querySelector('#make-status').textContent='Your work stays in this open tab as you change rooms. Refreshing or closing the tab clears it. Download a copy to keep it.';const swatches=document.querySelectorAll('[data-ink]');swatches.forEach(b=>{b.setAttribute('aria-pressed',b.dataset.ink===ink);const previous=b.onclick;b.onclick=()=>{previous();swatches.forEach(x=>x.setAttribute('aria-pressed',x===b));};});}if(route==='share'){document.querySelector('.share-paper .quiet').textContent='Your words stay in this open tab as you change rooms. They are not sent. Refreshing or closing clears them; download a copy to keep them.';}if(route==='journal'){document.querySelector('label[for=recall]').textContent='Try one sentence. It stays in this open tab until you refresh or close it.';}};
const roomNav=document.querySelector('header nav');const menuBar=document.createElement('div');menuBar.className='permanent-menu';roomNav.parentElement.insertAdjacentElement('afterend',menuBar);menuBar.append(roomNav);roomNav.setAttribute('aria-label','Main navigation');roomNav.innerHTML=[['journal','Read'],['library','Library'],['teaching','Teachings'],['catalog','Daily card'],['make','Make'],['quests','Side Quests'],['mail','Mail']].map(([r,n])=>`<a href="#${r}">${n}</a>`).join('')+'<a href="about.html">About</a>';
document.querySelector('.skip').onclick=e=>{e.preventDefault();const main=document.querySelector('#main');main.focus({preventScroll:true});main.scrollIntoView({behavior:'instant',block:'start'});};
window.addEventListener('hashchange',render);

