function updateRouteMetadata(){const route=document.body.dataset.room,slug=PAGE_ROUTES[route];if(!slug)return;const canonical='https://chaoticsunshine.com/'+(slug==='index'?'':slug);document.querySelector('link[rel=canonical]')?.setAttribute('href',canonical);}
render=function(){renderBeforeLaunch();document.querySelector('.review')?.remove();const metaSlug=PAGE_ROUTES[document.body.dataset.room];const meta=PAGE_META[metaSlug];document.title=meta?.title||routeNames[document.body.dataset.room]+' | Chaotic Sunshine';if(meta)document.querySelector('meta[name=description]')?.setAttribute('content',meta.description);document.querySelectorAll('a[href^="#"]').forEach(a=>{const key=a.getAttribute('href').slice(1);if(PAGE_ROUTES[key])a.setAttribute('href',PAGE_ROUTES[key]+'.html');});const firstNav=document.querySelector('.permanent-menu nav');if(firstNav)firstNav.querySelector('a').href='soul-snacks.html';document.querySelector('.footer-base').innerHTML='© 2026 Chaotic Sunshine · <a href="privacy.html">Privacy</a> · <a href="resource-permissions.html">Using the printables</a> · <a href="community-guidelines.html">Conversation guidelines</a>';document.querySelector('.footer-letter .button').href='subscribe.html';document.querySelector('.footer-letter .button').textContent='Join Sunshine Mail →';document.querySelector('.footer-letter h2').textContent='Join Sunshine Mail';document.querySelector('.footer-letter p').textContent='Devotions, Bible lessons, creative prompts, and little adventures. Monthly and free.';document.querySelectorAll('.permanent-menu a').forEach(a=>{const slug=PAGE_ROUTES[document.body.dataset.room];if(a.getAttribute('href')===slug+'.html')a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.querySelectorAll('textarea,input:not([type=email]):not([name])').forEach(el=>{if(el.id)el.addEventListener('input',()=>{const key=document.body.dataset.room;const fields={};document.querySelectorAll('main input[id],main textarea[id]').forEach(x=>{if(x.type!=='email'&&!x.name)fields[x.id]=x.value;});transientDrafts[key]={...(transientDrafts[key]||{}),fields};try{sessionStorage.setItem('cs-tab-drafts',JSON.stringify(transientDrafts));}catch{}});});document.querySelectorAll('.share-paper .quiet,#make-status,label[for=recall]').forEach(el=>{if(el.textContent.includes('Refreshing')||el.textContent.includes('refresh')||el.textContent.includes('not saved'))el.textContent='Your draft stays in this browser tab. Download a copy before closing the tab. Nothing is sent.';});updateRouteMetadata();};
// Full-page links preserve the server-rendered metadata and normal browser history.
const draftRooms=['make','journal','share','practice'];
function persistStudioDraft(){const route=document.body.dataset.room;if(!draftRooms.includes(route))return;const fields={};document.querySelectorAll('main input[id],main textarea[id]').forEach(el=>{if(!el.name&&el.type!=='email')fields[el.id]=el.value;});transientDrafts[route]={fields,sketch:document.querySelector('#sketch')?.toDataURL(),mode:document.querySelector('[data-make-mode][aria-pressed=true]')?.dataset.makeMode};try{sessionStorage.setItem('cs-tab-drafts',JSON.stringify(transientDrafts));}catch{const status=document.querySelector('#make-status,#share-status');if(status)status.textContent='This tab could not store the draft. Download your work before leaving.';}}
window.addEventListener('pagehide',persistStudioDraft);
const renderBeforeStorage=render;render=function(){renderBeforeStorage();const route=document.body.dataset.room;if(draftRooms.includes(route)){document.querySelectorAll('main textarea,main input:not([name])').forEach(el=>el.addEventListener('input',persistStudioDraft));const canvas=document.querySelector('#sketch');if(canvas){canvas.addEventListener('pointerup',persistStudioDraft);canvas.addEventListener('pointercancel',persistStudioDraft);}document.querySelectorAll('[data-make-mode],#clear-sketch').forEach(el=>el.addEventListener('click',persistStudioDraft));document.querySelectorAll('.share-paper .quiet,#make-status,label[for=recall]').forEach(el=>{if(/tab|refresh|saved|clears/i.test(el.textContent))el.textContent='Your draft stays in this browser tab. Download a copy before closing the tab. Nothing is sent.';});}};

const csFirstLesson='Your Prayer Does Not Need a Cover Letter';
const csLessonLabel=step=>'<p class="quiet"><strong>'+csFirstLesson+'</strong> · Romans 8:12–17 · '+step+'</p>';
const csHome=pages.home;
pages.home=()=>csHome().replace('href="teaching-shelf.html"><img src="assets/prayer-cover-letter-illustration.webp"','href="soul-snack-01.html"><img src="assets/prayer-cover-letter-illustration.webp"').replace('Open the illustrated collection','Try a 3-minute illustrated lesson').replace('See a Bible idea come to life.','Start with one honest prayer.').replace('href="welcome.html">Peek inside Sunshine Mail','href="sunshine-mail-sample.html">Peek inside Sunshine Mail').replace('href="#welcome"><span class="object-tag">SUNSHINE MAIL','href="sunshine-mail-sample.html"><span class="object-tag">SUNSHINE MAIL').replace('Open the illustrated reflection →','Try the 3-minute lesson →');
const csMail=pages.mail;
pages.mail=()=>csMail().replaceAll('href="welcome.html"','href="sunshine-mail-sample.html"').replace('href="#welcome"','href="sunshine-mail-sample.html"');
const csJournal=pages.journal;
pages.journal=()=>csJournal().replace('BELOVED FIRST · DAY 1 · ABOUT 3 MINUTES','GUIDED LESSON · STEP 1 OF 4 · ABOUT 3 MINUTES').replace('href="#make"','href="make.html"').replace('Make a small response →','Continue to Make →').replace(/<div class="journal-bottom">[\s\S]*?<\/div>/,'').replace(/<section class="section"><div class="wrap"><a href="soul-snacks.html"[\s\S]*?<\/section>/,'');
const csMake=pages.make;
pages.make=()=>csMake().replace('THE STUDIO TABLE','STEP 2 OF 4 · MAKE').replace('<p>After reading Romans',csLessonLabel('Make')+'<p>After reading Romans');
const csTry=pages.practice;
pages.practice=()=>csTry().replace('INTO THE LIFE YOU ALREADY HAVE','STEP 3 OF 4 · TRY').replace('<p>Romans 8:12–17 describes',csLessonLabel('Try')+'<p>Romans 8:12–17 describes').replace(/<a[^>]*>Or choose a little Side Quest ↗<\/a>/,'').replace('Keep or share what you noticed →','Finish the lesson →');
const csShare=pages.share;
pages.share=()=>csShare().replace('THE GOOD THINGS TRAVEL','STEP 4 OF 4 · OPTIONAL SHARE').replace('<p>You don’t have to show',csLessonLabel('Share')+'<p>You don’t have to show').replace(/<a[^>]*>Or keep a quiet good thing →<\/a>/,'')+'<section class="section last-invitation"><div class="wrap"><span class="eyebrow">TAKE IT INTO THE WORLD</span><h2>You read it. You made it. Now live it.</h2><p>Tomorrow, before reopening Romans 8:12–17, recall one thing about belonging. Then check the passage again.</p><a class="button" href="subscribe.html">Join Sunshine Mail →</a> <a class="text-link" href="soul-snacks.html">Explore another reading</a></div></section>';
const csRender=render;
render=function(){csRender();const room=document.body.dataset.room;if(['journal','make','practice','share'].includes(room)){document.querySelectorAll('.journey-navigation').forEach(n=>n.remove());if(room==='make'){const next=document.querySelector('.carry-on a');if(next){next.textContent='Continue to Try →';next.classList.add('button');}}}document.querySelectorAll('.permanent-menu a').forEach(a=>{if(a.textContent.trim()==='Site Map'){a.textContent='Find by topic or verse';a.href='site-map.html#smart-search';}});};
const initialHash=location.hash.slice(1);if(initialHash.startsWith('teaching-')){const i=TEACHING.items.findIndex(x=>'teaching-'+x.slug===initialHash);if(i>=0)selectedTeaching=i;}if(initialHash.startsWith('quest-')){const i=quests.findIndex(x=>'quest-'+x.id===initialHash);if(i>=0)questIndex=i;}
const initialRoute=routeFromPath();if(PAGE_ROUTES[initialHash]&&PAGE_ROUTES[initialHash]!==PAGE_ROUTES[initialRoute])location.replace(PAGE_ROUTES[initialHash]+'.html');document.body.dataset.room=''; // Server markup is not an unsaved client draft.
render();

if(initialHash.startsWith('quest-'))requestAnimationFrame(()=>document.querySelector('#mission')?.scrollIntoView({block:'start',behavior:'instant'}));
if(initialHash.startsWith('teaching-'))requestAnimationFrame(()=>document.querySelector('#teaching-preview')?.scrollIntoView({block:'start',behavior:'instant'}));
document.body.dataset.clientReady='true';
